        console.log(`Fetching dashboard data from: ${dashboardUrl}`);
        const dashboardResponse = await fetch(dashboardUrl);
        
        // --- CHECK 1: Was the network request successful? ---
        if (!dashboardResponse.ok) {
            throw new Error(`Failed to fetch dashboard data: Server responded with ${dashboardResponse.status}`);
        }

        // --- CHECK 2: Did the server send JSON? ---
        const dashboardContentType = dashboardResponse.headers.get("content-type");
        if (!dashboardContentType || !dashboardContentType.includes("application/json")) {
            throw new TypeError(`Expected JSON from /dashboard/ but got HTML. Check your ROOT urls.py file.`);
        }
        
        const data = await dashboardResponse.json();

        if (data.redirect_to === '/health-assessment') {
            navigate('/health-assessment');
            return; // Stop execution
        }

        setDashboardData(data); // This sets stations and forecasts
        setHealthData(data.health_data); // This sets health score

