        const location = await getUserLocation();
        console.log('📍 Location obtained:', location);
        setUserLocation(location); // Save user location

        // 3. Fetch the PERSONALIZED AQI from our new backend endpoint
        // --- START: THE FIX ---
        // Your urls.py has 'user-aqi/', not 'api/user-aqi/'.
        const aqiUrl = `${API_BASE_URL}/user-aqi/?lat=${location.lat}&lng=${location.lng}`;
        // --- END: THE FIX ---
        
        console.log(`Fetching user AQI from: ${aqiUrl}`);
