        }

        // --- CHECK 2: Did the server send JSON? ---
        const aqiContentType = aqiResponse.headers.get("content-type");
        if (!aqiContentType || !aqiContentType.includes("application/json")) {
            throw new TypeError(`Expected JSON from /user-aqi/ but got HTML. Check server logs for a crash.`);
        }

        // ... inside loadDashboard() ...

        const aqiData = await aqiResponse.json();

        // 4. Set the main AQI data
        setCurrentDataInfo({
            aqi: aqiData.user_aqi,
            station_name: `Your Location (Calculated)`,
            is_interpolated: true,
            distance_message: `📍 ${aqiData.closest_sensor.distance_km.toFixed(1)}km from nearest sensor.`,
            data_type: 'Your Location Data (Calculated)',
            
            // --- THIS IS THE FIX ---
            values: aqiData.interpolated_values || {} // Use the values from the API
            // --- END OF FIX ---
        });

        // 5. *** THIS IS THE FIX FOR THE FORECAST ***
        // Set the nearestStationInfo state so the forecast chart knows which station to use.
        setNearestStationInfo({
            id: aqiData.closest_sensor.sensor_id,
            name: data.stations[aqiData.closest_sensor.sensor_id]?.station_info?.name || aqiData.closest_sensor.sensor_id,
            distance: aqiData.closest_sensor.distance_km
